"""Ascend implementation of the six ``aten::_foreach_lerp`` overloads.

``lerp(self, end, weight) = self + weight * (end - self)`` for every position
of the tensor list, with the weight supplied three different ways:

===============  ==========================================================
overload         weight
===============  ==========================================================
``.List``        a ``Tensor[]`` paired position by position with ``self``
``.Scalar``      one Python number shared by every position
``.ScalarList``  a ``Scalar[]`` with one number per position
===============  ==========================================================

Each overload also has an in-place form (``_foreach_lerp_``) that writes back
into ``self`` and returns ``None``.

Why this module exists
----------------------
The generic executor (``flag_gems.utils.foreach.foreach_ternary``) launches
``len(tensors)`` programs, one per list entry, and every program then walks the
*whole* tensor serially.  That is the right shape for a single large tensor and
the wrong shape here: for the benchmark's sixteen equal tensors it leaves almost
all of the vector cores idle and measured 0.02-0.10x of ATen.  The scalar
weight overloads additionally fail to compile on this backend with
``BiShengIR ... PassManager::run failed``.

The implementation below issues exactly **one kernel per (dtype, numel) group**
for the whole list (normally one launch per call) and passes the per-tensor
addresses through a small int64 table instead of 16x4 pointer arguments, which
keeps both the launch and the generated launcher small.

Layout of the fused kernel
--------------------------
``grid = (per_tensor_programs, num_tensors)``: the second program axis selects
the tensor (a uniform scalar branch, so the loads below it are normally
vectorised) and the first splits that tensor into a few contiguous tile ranges.
The number of tiles per tensor is derived from the device's AIV core count, so a
call normally occupies a single wave of cores rather than thousands of tiny
blocks: on this hardware the per-block fixed cost was the dominant term, and
collapsing 2048 blocks into 32 measured 3x faster at 1024**2.

Two details are required by the Ascend lowering and are not stylistic:

* the tile offset must stay affine in the loop variable (``tile * BLOCK +
  arange``).  Computing it from a division result, as the single-grid variant
  does, breaks the masked-access lowering
  (``ConvertTritonIRToLinalgIR ... layout mismatch``).
* fp16/bf16 are computed in fp32 and rounded once on the store, matching ATen's
  opmath.

Anything outside the fast path (mixed dtypes, views, aliased in-place entries,
fp64, integer operands) is handed to the generic wrapper unchanged so that the
reference semantics, including its error messages, are preserved.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

# Elements per program tile.  32 KiB of fp32 traffic per stream; four live
# streams still fit in UB, and the sweep over 1024/2048/4096/8192/16384 was
# monotonically better up to this size (16384 overflows).
_BLOCK = 8192

_INT32_LIMIT = 1 << 31
_GRID_CAP = 65535

# ``lerp`` is floating point only in ATen: an integral lerp would have to round
# the interpolation and ATen refuses instead.
_FLOAT_DTYPES = frozenset((torch.float16, torch.bfloat16, torch.float32))

_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
}

# Weight handling, selected by a constexpr so one kernel serves all three
# overloads.
_MODE_TENSOR = 0
_MODE_SCALAR = 1
_MODE_SCALAR_LIST = 2


def _aiv_core_count():
    """Vector core count, used to size the launch to a single wave."""
    try:
        from triton.runtime import driver

        return max(1, int(driver.active.utils.get_aivector_core_num()))
    except Exception:  # pragma: no cover - defensive, older drivers
        return 40


_AIV_CORES = _aiv_core_count()


# ---------------------------------------------------------------------------
# device kernel
# ---------------------------------------------------------------------------


@triton.jit
def _lerp_kernel(
    meta,
    waux,
    n,
    tiles,
    NT,
    wscalar,
    BLOCK: tl.constexpr,
    DT: tl.constexpr,
    MODE: tl.constexpr,
    EVEN: tl.constexpr,
):
    """``dst = src + w * (end - src)`` for the tensors of one group.

    ``meta`` is an int64 table laid out ``[dst | src | end | weight]``, each
    block ``NT`` entries wide.  The weight block is only present for
    ``MODE == 0``; ``MODE == 2`` reads its per-tensor scalars from ``waux``
    (fp32) and ``MODE == 1`` uses the ``wscalar`` kernel argument.

    ``EVEN`` means ``n`` is a multiple of ``BLOCK``, which removes the tail
    mask (and its compare / masked-lowering) from the common path.
    """
    pid = tl.program_id(0)
    t = tl.program_id(1)
    # Programs on axis 0 split this tensor into equal contiguous tile runs.
    npr = tl.num_programs(0)
    per = (tiles + npr - 1) // npr
    lo = pid * per
    hi = tl.minimum(lo + per, tiles)

    dst = tl.cast(tl.load(meta + t), tl.pointer_type(DT))
    src = tl.cast(tl.load(meta + NT + t), tl.pointer_type(DT))
    end = tl.cast(tl.load(meta + 2 * NT + t), tl.pointer_type(DT))
    if MODE == 0:
        wptr = tl.cast(tl.load(meta + 3 * NT + t), tl.pointer_type(DT))
    else:
        wptr = dst  # unused on the other modes; keeps the trace uniform

    # The tile offset has to stay affine in ``tile``: an offset derived from a
    # division makes the masked load/store lowering fail on this backend.
    for tile in range(lo, hi):
        off = tile * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            a = tl.load(src + off).to(tl.float32)
            b = tl.load(end + off).to(tl.float32)
            if MODE == 0:
                w = tl.load(wptr + off).to(tl.float32)
            elif MODE == 1:
                w = wscalar
            else:
                w = tl.load(waux + t)
            tl.store(dst + off, (a + w * (b - a)).to(DT))
        else:
            m = off < n
            a = tl.load(src + off, mask=m, other=0.0).to(tl.float32)
            b = tl.load(end + off, mask=m, other=0.0).to(tl.float32)
            if MODE == 0:
                w = tl.load(wptr + off, mask=m, other=0.0).to(tl.float32)
            elif MODE == 1:
                w = wscalar
            else:
                w = tl.load(waux + t)
            tl.store(dst + off, (a + w * (b - a)).to(DT), mask=m)


