# ---------------------------------------------------------------------------


def _generic(mode, inplace):
    """The generic wrapper for one overload; used for every irregular call.

    Imported lazily: the vendor ``ops`` package is imported while
    ``flag_gems`` itself is still initialising, and this keeps the import order
    independent.
    """
    from flag_gems.ops import _foreach_binary

    suffix = {
        _MODE_TENSOR: "List",
        _MODE_SCALAR: "Scalar",
        _MODE_SCALAR_LIST: "ScalarList",
    }[mode]
    name = f"_foreach_lerp{'_' if inplace else ''}_{suffix}"
    return getattr(_foreach_binary, name)


# ---------------------------------------------------------------------------
# host side
# ---------------------------------------------------------------------------


def _per_tensor_programs(tiles, nt):
    """Programs per tensor: one wave of vector cores over the whole list.

    With ``nt`` tensors in the group and ``_AIV_CORES`` cores, every tensor
    gets ``cores // nt`` contiguous tile ranges (at least one).  Measured on
    256**2 / 512**2 / 1024**2: this beats both one block per tile (3x) and one
    block per tensor, and is flat over the 2-10 range for the large shapes.
    """
    per = _AIV_CORES // nt
    if per < 1:
        per = 1
    if per > tiles:
        per = tiles
    # grid = (per, nt) and the product is the API limit.
    if per * nt > _GRID_CAP:
        per = max(1, _GRID_CAP // nt)
    return max(1, per)


def _launch(entries, dtype, n, mode, wscalar=None):
    """One fused launch for a group of equal ``(dtype, numel)`` entries."""
    nt = len(entries)
    tiles = (n + _BLOCK - 1) // _BLOCK
    nprog = _per_tensor_programs(tiles, nt)
    device = entries[0][0].device

    ptrs = [e[0].data_ptr() for e in entries]
    ptrs += [e[1].data_ptr() for e in entries]
    ptrs += [e[2].data_ptr() for e in entries]
    if mode == _MODE_TENSOR:
        ptrs += [e[3].data_ptr() for e in entries]
    meta = torch.tensor(ptrs, dtype=torch.int64, device=device)

    if mode == _MODE_SCALAR_LIST:
        waux = torch.tensor([e[3] for e in entries], dtype=torch.float32, device=device)
        wscalar = 0.0
    else:
        # Unused by the other modes; a real tensor keeps the pointer argument
        # well typed.
        waux = entries[0][0]

    _lerp_kernel[(nprog, nt)](
        meta,
        waux,
        n,
        tiles,
        nt,
        wscalar,
        BLOCK=_BLOCK,
        DT=_TL_DTYPE[dtype],
        MODE=mode,
        EVEN=(n % _BLOCK == 0),
    )


def _run(self, ends, weight, inplace, mode):
    """Validate, bucket by ``(dtype, numel)`` and launch one kernel per bucket."""
    plain = _generic(mode, inplace)

    if not isinstance(self, (list, tuple)) or not isinstance(ends, (list, tuple)):
        return plain(self, ends, weight)
    self_list = list(self)
    end_list = list(ends)
    if not self_list or len(self_list) != len(end_list):
        return plain(self, ends, weight)
    if len(self_list) > _GRID_CAP:
        # The tensor index travels on the second grid axis, which has the same
        # per-dimension limit.
        return plain(self, ends, weight)

    wscalar = None
    if mode == _MODE_TENSOR:
        if not isinstance(weight, (list, tuple)) or len(weight) != len(self_list):
            return plain(self, ends, weight)
        w_list = list(weight)
        if not all(type(w) is torch.Tensor for w in w_list):
            return plain(self, ends, weight)
        wvals = None
    elif mode == _MODE_SCALAR:
        if isinstance(weight, (torch.Tensor, list, tuple)):
            return plain(self, ends, weight)
        try:
            wscalar = float(weight)
        except (TypeError, ValueError):
            return plain(self, ends, weight)
        w_list = None
        wvals = None
    else:
        if not isinstance(weight, (list, tuple)) or len(weight) != len(self_list):
            return plain(self, ends, weight)
        w_list = list(weight)
        if any(isinstance(w, torch.Tensor) for w in w_list):
            return plain(self, ends, weight)
        try:
            wvals = [float(w) for w in w_list]
        except (TypeError, ValueError):
            return plain(self, ends, weight)

    outs = [None] * len(self_list)
    buckets = {}
    seen = set()
    for i in range(len(self_list)):
        a = self_list[i]
        b = end_list[i]
        if type(a) is not torch.Tensor or type(b) is not torch.Tensor:
            return plain(self, ends, weight)
        dt = a.dtype
        if dt not in _FLOAT_DTYPES or b.dtype is not dt:
            return plain(self, ends, weight)
        if a.shape != b.shape or not (a.is_contiguous() and b.is_contiguous()):
            return plain(self, ends, weight)
        n = a.numel()
        if n >= _INT32_LIMIT:
            return plain(self, ends, weight)
        wval = None
        if mode == _MODE_TENSOR:
            w = w_list[i]
            if w.dtype is not dt or w.shape != a.shape or not w.is_contiguous():
                return plain(self, ends, weight)
            wval = w
        elif mode == _MODE_SCALAR_LIST:
            wval = wvals[i]
        if inplace:
            p = a.data_ptr()
            if p in seen:
                # ATen applies list entries in order; two positions on one
                # storage would race inside a single fused launch.
                return plain(self, ends, weight)
            seen.add(p)
            dst = a
            outs[i] = a
        else:
            dst = torch.empty_like(a)
            outs[i] = dst
        if n:
            buckets.setdefault((dt, n), []).append((dst, a, b, wval))

    for (dt, n), entries in buckets.items():
        _launch(entries, dt, n, mode, wscalar)

    return None if inplace else outs


def foreach_lerp_list(self, tensors1, weight):
    """``aten::_foreach_lerp.List``: ``self[i] + weight[i] * (tensors1[i] - self[i])``."""
    logger.debug("GEMS _FOREACH_LERP")
    return _run(self, tensors1, weight, False, _MODE_TENSOR)


